"""Render the public audio shelf from its committed category and location catalog."""
from pathlib import Path
from html import escape
import json,csv,io
ROOT=Path(__file__).resolve().parents[1]
DEST=ROOT/'site/sounds'
def build():
 data=json.loads((DEST/'catalog.json').read_text());locs={l['id']:l for l in data['locations']};parts=[]
 for e in data['entries']:
  search=' '.join([e['title'],e['category'],e['description'],*e['tags'],*(locs[x]['name']+' '+str(locs[x]['atlas_id']) for x in e['locations'])]).casefold()
  group_tags=' '.join(e['groups'])
  parts.append(f'<article class="sound-card" id="{e["id"]}" data-kind="{e["kind"]}" data-group="{group_tags}" data-new="{str(e["new"]).lower()}" data-search="{escape(search,quote=True)}"><div class="card-top"><span class="kind">{e["kind"].title()}</span>'+('<span class="new">New addition</span>' if e['new'] else '<span class="existing">Existing library</span>')+f'</div><h3>{escape(e["title"])}</h3><p class="tags">{escape(e["category"])}</p><p>{escape(e["description"])}</p>')
  parts.append(f'<p class="usage">{escape(e["status"])}</p>')
  for i,c in enumerate(e['clips']):
   title=e['title']+' · '+c['label'];parts.append(f'<div class="clip"><label for="audio-{e["id"]}-{i}">{escape(c["label"])}</label><audio id="audio-{e["id"]}-{i}" controls preload="none" aria-label="{escape(title,quote=True)}" src="{c["src"]}">Your browser cannot play this audio. Use the download link.</audio><a class="download" href="{c["src"]}" download>Download {escape(c["label"].lower())}</a></div>')
  if e['locations']:
   parts.append(f'<details class="locations"><summary>Used in {len(e["locations"])} locations</summary><ul>'+''.join(f'<li><a href="../wiki.html#{locs[x]["topic_id"]}">{escape(locs[x]["name"])}</a></li>' for x in e['locations'])+'</ul></details>')
  if e.get('related'):
   parts.append('<details class="locations"><summary>Connected lore &amp; topics</summary><ul>'+''.join(f'<li><a href="../{escape(link["href"],quote=True)}">{escape(link["title"])}</a></li>' for link in e['related'])+'</ul></details>')
  if e.get('player_href'):parts.append(f'<p><a href="../{e["player_href"]}">Full song player · voices &amp; other arrangements</a></p>')
  parts.append('</article>')
 table=[];entries={e['id']:e for e in data['entries']}
 for l in data['locations']:
  search=' '.join([l['name'],str(l['atlas_id']),l['floor_tag'],l['ambience_tag'],entries[l['music']]['title']]).casefold()
  table.append(f'<tr id="location-{l["atlas_id"]}" data-search="{escape(search,quote=True)}"><th scope="row"><small>Atlas {l["atlas_id"]:03d}</small><a href="../wiki.html#{l["topic_id"]}">{escape(l["name"])}</a></th><td><a href="#{l["music"]}">{escape(entries[l["music"]]["title"])}</a></td><td><a href="#amb_{l["ambience_tag"]}">{escape(l["ambience_tag"].replace("_"," "))}</a></td><td><a href="#step_{l["floor_tag"]}"><code>{l["floor_tag"]}</code></a></td></tr>')
 page='''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#103f5a"><title>Sound library · Cyber Pet Lore</title><meta name="description" content="Listen to the Cyber Pet soundtrack, environmental ambience and footsteps. Browse music categories and floor tags for all 106 Atlas locations."><link rel="stylesheet" href="../style.css"><link rel="stylesheet" href="sounds.css"><link rel="stylesheet" href="../navigation.css"></head>
<body><a class="skip" href="#sound-main">Skip to sound library</a><header class="masthead"><a href="../index.html" class="brand"><span class="brand-icon" aria-hidden="true">◇</span><span>CYBER PET <b>LORE</b><small>THE READING ARCHIVE</small></span></a><nav aria-label="Main"><a href="../index.html">Library</a></nav></header>
<main id="sound-main"><header class="sound-hero"><p class="eyebrow">THE LISTENING SHELF</p><h1>Sounds woven into the world.</h1><p>Music sets the mood. Ambience gives a place its atmosphere. Footsteps follow the ground beneath a character’s feet.</p><div class="sound-stats"><span><strong>42</strong> game music tracks</span><span><strong>14</strong> ambience families</span><span><strong>12</strong> floor materials</span><span><strong>106</strong> mapped locations</span></div><p class="intro-note">Listen within location readings and topic pages, or browse the complete collection here: 244 game audio clips and four Era Zero song performances. Includes Soft Circuit, activity music, game effects and labeled Tactical course previews.</p><a class="table-link" href="#location-map">Look up a location’s floor tag ↓</a></header>
<section class="shelf" aria-labelledby="browse-title"><div class="section-heading"><div><p class="eyebrow">BROWSE & LISTEN</p><h2 id="browse-title">One library. Shared categories.</h2></div><button type="button" id="stop-all">Stop audio</button></div>
<form id="sound-filters" class="sound-filters" role="search"><label class="search-label">Find a sound or location<input id="sound-search" type="search" placeholder="Snow, archive, Cacheboard…"></label><label>Sound type<select id="sound-kind"><option value="">All sounds</option><option value="music">Background music</option><option value="ambience">Environmental ambience</option><option value="footstep">Footsteps by floor</option><option value="effect">Game sound effects</option><option value="voice">Spoken encouragement</option><option value="song">Era Zero songs</option></select></label><label>Related topic<select id="sound-group"><option value="">All topics</option>GROUP_OPTIONS</select></label><label>Collection<select id="sound-new"><option value="">Complete library</option><option value="new">Latest additions</option><option value="existing">Existing library</option></select></label><button type="reset">Reset</button></form><div class="playback-options"><label><input id="loop-audio" type="checkbox"> Repeat music and ambience</label><span>Press Play to listen. Only one clip plays at a time.</span></div><p id="sound-count" role="status" aria-live="polite">217 entries · 248 audio clips</p><noscript><p>All clips and location assignments are available below. Search, filters and automatic single-clip playback need JavaScript.</p></noscript><p id="sound-empty" hidden>No sounds match. Try a broader search or reset the filters.</p><div class="sound-grid">'''+''.join(parts)+'''</div></section>
<section class="location-map" id="location-map" aria-labelledby="map-title"><p class="eyebrow">THE ATLAS SOUND MAP</p><h2 id="map-title">What does this location sound like?</h2><p>Each place has its own music tags, ambience tag and floor tag. Floor material is independent of biome, friction and weather. Renderings share their location’s assignment unless explicitly overridden.</p><label>Find a location or material<input id="location-search" type="search" placeholder="Location name, Atlas number, mud…"></label><p><a href="locations.csv" download>Download the location sound map (CSV)</a></p><div class="sound-table-wrap"><table><caption>Music, ambience and floor assignments for all 106 Atlas locations</caption><thead><tr><th scope="col">Location</th><th scope="col">Music</th><th scope="col">Ambience</th><th scope="col">Floor tag</th></tr></thead><tbody>'''+''.join(table)+'''</tbody></table></div><p id="location-count" role="status" aria-live="polite">106 locations</p></section>
<section class="sound-notes"><h2>How the sounds work</h2><p>Location music and ambience are shared by category. Footsteps play only while a character walks on a surface, with several variations per material. Jumping and pauses stop the walking cadence. Music and sound effects have separate volume controls in the game.</p><p>All 106 locations have an explicit music assignment. Unknown custom backgrounds use Fablewood, a neutral stone floor and no assigned ambience. Low happiness (below 35) switches care music to <em>When the Hearth Grows Quiet</em>. <em>Fablewood in the Rain</em> remains in the library as a retained mood variant.</p><p>'''+escape(data['attribution'])+'''</p><p class="small-note">Assignments are production choices for the game. Updated 22 November 2026. <a href="catalog.json">Audio catalog and source file checksums</a>.</p></section></main><footer><a href="../index.html">Return to the lore book</a></footer><script type="module" src="sounds.mjs"></script><script type="module" src="../navigation.mjs"></script></body></html>'''
 page=page.replace('GROUP_OPTIONS',''.join(f'<option value="{g["id"]}">{escape(g["title"])}</option>' for g in data['groups']))
 page=page.replace('217 entries · 248 audio clips',str(len(data['entries']))+' entries · '+str(sum(len(e['clips']) for e in data['entries']))+' audio clips')
 (DEST/'index.html').write_text(page)
 out=io.StringIO();writer=csv.writer(out);writer.writerow(['Atlas ID','Location','Music title','Music tags','Ambience tag','Floor tag'])
 for l in data['locations']:writer.writerow([l['atlas_id'],l['name'],entries[l['music']]['title'],', '.join(l['music_tags']),l['ambience_tag'],l['floor_tag']])
 (DEST/'locations.csv').write_text(out.getvalue());print('Sound library:',sum(len(e['clips']) for e in data['entries']),'clips;',len(data['locations']),'locations')
if __name__=='__main__':build()
